# owner: platform
import unittest

from rosterkit.models import Student
from rosterkit.errors import ProjectError
from rosterkit.contacts import contact_rows


def make_student(last, first, section, email):
    return Student(
        "id-" + last, last, first, section, email
    )


class ContactRowTests(unittest.TestCase):
    def test_rows_are_sorted_and_aligned(self):
        rows = contact_rows(
            [
                make_student("Young", "Al", "B", "al@x.t"),
                make_student("Adams", "Bea", "A", "bea@x.t")
            ]
        )
        self.assertEqual(
            rows,
            [
                "Adams, Bea  A  bea@x.t",
                "Young, Al   B  al@x.t"
            ]
        )

    def test_missing_email_names_student(self):
        nomail = make_student("Adams", "Bea", "A", None)
        with self.assertRaises(ProjectError) as caught:
            contact_rows([nomail])
        self.assertIn("Adams, Bea", str(caught.exception))

    def test_empty_list_raises(self):
        with self.assertRaises(ProjectError):
            contact_rows([])
